public class FlagPainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String colorAt(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "(null image)";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static String hex(java.awt.Color c) {
        return String.format("#%06X", c.getRGB() & 0xFFFFFF);
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage img =
                    new java.awt.image.BufferedImage(90, 90, java.awt.image.BufferedImage.TYPE_INT_RGB);
            java.awt.Graphics2D g = img.createGraphics();
            try {
                FlagPainter.paint(g, 90, 90);
            } finally {
                g.dispose();
            }
            check("90x90 top stripe is red", hex(java.awt.Color.RED), colorAt(img, 45, 15));
            check("90x90 middle stripe is white", hex(java.awt.Color.WHITE), colorAt(img, 45, 45));
            check("90x90 bottom stripe is blue", hex(java.awt.Color.BLUE), colorAt(img, 45, 75));
            check("90x90 stripe spans full width", hex(java.awt.Color.RED), colorAt(img, 4, 15));
            java.awt.image.BufferedImage wide =
                    new java.awt.image.BufferedImage(120, 60, java.awt.image.BufferedImage.TYPE_INT_RGB);
            java.awt.Graphics2D g2 = wide.createGraphics();
            try {
                FlagPainter.paint(g2, 120, 60);
            } finally {
                g2.dispose();
            }
            check("120x60 top stripe is red", hex(java.awt.Color.RED), colorAt(wide, 60, 10));
            check("120x60 middle stripe is white", hex(java.awt.Color.WHITE), colorAt(wide, 60, 30));
            check("120x60 bottom stripe is blue", hex(java.awt.Color.BLUE), colorAt(wide, 60, 50));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

